mapper.insert:
insert into conversation_session (
  session_id, user_id, title, status, kb_scope, asset_scope, created_at, updated_at
) values (
  #{sessionId}, #{userId}, #{title}, #{status}, #{kbScope}, #{assetScope}, #{createdAt}, #{updatedAt}
) on duplicate key update
  user_id = values(user_id), title = values(title), status = values(status),
  kb_scope = values(kb_scope), asset_scope = values(asset_scope), updated_at = values(updated_at),
  deleted_at = null

mapper.select:
select session_id, user_id, title, status, kb_scope, asset_scope, created_at, updated_at
from conversation_session
where user_id = #{userId}
  and deleted_at is null
order by updated_at desc, session_id desc
limit #{limit}
